Call `getActionState(ctx)` in the action handler, passing the Astro API context object (`ctx`) as the argument. It returns a promise resolving to `{ data, error }` matching the client-side state type.

```ts
import { getActionState } from '@astrojs/react/actions';

export const server = {
  like: defineAction({
    input: z.object({ postId: z.string() }),
    handler: async ({ postId }, ctx) => {
      const { data: currentLikes = 0, error } = await getActionState<SafeResult<any, number>>(ctx);
      if (error) throw error;
      return currentLikes + 1;
    },
  }),
};
```

